from logging import getLogger

from taf.internal.robot_typecasts.typecasts import time_to_seconds

from .exceptions import WatchdogNotStarted
from .watchdog import Watchdog


class status_watchdog(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self._watchdog = None
        self._logger = getLogger()

    def watch_statuses(self, bts_config=None, interval=2.0, log_dir=''):
        """
        Starts watching current statuses on BTS to detect any occurrence of unexpected status.

        Doesn't block test execution, status watching is done in parallel with main thread.
        Must always be used together with stop_watching_statuses keyword, preferably put in test's teardown.
        After starting status watch it will wait one interval for potential unexpected statuses to be read from BTS.
        If current statuses cannot be read from BTS (due to its unavailability) then status watch doesn't get stopped.
        Works with gnB Classical BTS topology.

        BTS is asked for current statuses every time when time interval passes.
        Unexpected statuses are those which were not expected either via expect_status nor expect_statuses keywords.
        If unexpected status is detected then it is saved in watch history.
        If unexpected status stops being read from BTS then it is marked as lost in watch history.
        Detected unexpected status history can be checked with check_unexpected_statuses keyword.

        :param bts_config: configuration object of BTS to which requests for current statuses will be send;
                           should contain all data required to connect to given BTS;
                           defaults to None (ClassicalBts with default connection details will be used)
        :type bts_config: taf.config.testline.gnb.gnb.gNB or None
        :param interval: time interval between consecutive requests to BTS for current statuses;
                         accepts Robot string time format i.e. 1 min 30 sec; defaults to 2 sec
        :type interval: float or int or str
        :param log_dir: path to directory where additional logs will be stored;
                        defaults to '' (logs will be stored in current working directory)
        :type log_dir: str
        :raises InvalidBtsType: when requested BTS type from BTS config is unsupported
        :raises WatchdogAlreadyStarted: when re-starting statuses watch was not preceded with stopping statuses watch
        :raises BtsConnectionError: when connection to BTS cannot be established
        """
        self._logger.info("Starting status watch")

        if not self._watchdog:
            self._watchdog = Watchdog(bts_config=bts_config, interval=time_to_seconds(interval))

        self._watchdog.watch_statuses(log_dir=log_dir)
        self._logger.info("Watching statuses with {}s interval".format(interval))

    def expect_status(self, component, name, value, check_component=False):
        """
        Adds single status to list of expected statuses.

        Before using this keyword status watchdog needs to be started - watch_statuses keyword must be used first.
        If (at any point in time) this expected status will not be read from BTS,
        then such event will be recorded in watch history.
        Can be used to dynamically change expected statuses during test case execution.

        :param component: runtime distName of component for which given status should be expected
                          i.e. '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1'
        :type component: str
        :param name: name of expected status, i.e. 'availabilityStatus'
        :type name: str
        :param value: value of expected status, i.e. 'Offline';
                      use None when expecting status without value (i.e. 'Online' after CNI-61110)
        :type value: str or None
        :param check_component: flag indicating whether component existence should be checked before adding
                                expected status; defaults to False
        :type check_component: bool
        :raises WatchdogNotStarted: when performing this action was not preceded with starting status watch
        :raises InvalidStatus: when expected status has invalid data
        :raises ComponentCheckError: when BTS was unavailable during component check or
                                     given component doesn't exist on BTS
        """
        self._logger.info("Adding expected status with component: {}, name: {} and value: {}".format(
            component, name, value))
        self._check_for_not_initialized_watchdog(self.expect_status.__name__)
        self._watchdog.add_expected_status(component=component, name=name, value=value, check_component=check_component)

    def expect_statuses(self, statuses, check_component=False):
        """
        Adds multiple statuses to list of expected statuses.

        Before using this keyword status watchdog needs to be started - watch_statuses keyword must be used first.
        If (at any point in time) any of this expected statuses will not be read from BTS,
        then such event will be recorded in watch history.
        Can be used to dynamically change expected statuses during test case execution.

        :param statuses: data of statuses which should be expected;
                         should be in form of dictionary {component: {name: value}});
                         use None for value when expecting status without value (i.e. 'Online' after CNI-61110)
        i.e.
        {'/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-2': {'availabilityStatus': 'Offline',
                                                                                'operationalState': 'Disabled'},
         '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/NRBTS_R-50304/NRCELL_R-1': {'administrativeState': 'Unlocked'}}
        :type statuses: {str: {str: str}}
        :param check_component: flag indicating whether components existence should be checked before adding
                                expected statuses; defaults to False
        :type check_component: bool
        :raises WatchdogNotStarted: when performing this action was not preceded with starting status watch
        :raises InvalidStatus: when expected status has invalid data
        :raises ComponentCheckError: when BTS was unavailable during component check or
                                     given component doesn't exist on BTS
        """
        self._logger.info("Adding expected statuses:\n{}".format(statuses))
        self._check_for_not_initialized_watchdog(self.expect_statuses.__name__)

        for component, names_and_values in statuses.items():

            if not names_and_values:
                names_and_values = {None: None}

            self._watchdog.add_expected_statuses(component=component, names_and_values=names_and_values,
                                                 check_component=check_component)

    def expect_statuses_with_stop_conditions(self, statuses, stop_conditions, check_component=False):
        """
        Adds multiple statuses to list of expected statuses with stop condition. When all the statuses from
        stop_conditions are met, status watch on the statuses will be stopped.

        Before using this keyword status watchdog needs to be started - watch_statuses keyword must be used first.
        If (at any point in time) any of this expected statuses will not be read from BTS,
        then such event will be recorded in watch history.
        Can be used to dynamically change expected statuses during test case execution.
        Stop condition is used to stop status watch when given statuses are read from BTS.

        :param statuses: data of statuses which should be expected;
                         should be in form of dictionary {component: {name: value}});
                         use None for value when expecting status without value (i.e. 'Online' after CNI-61110)
        i.e.
        {'/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-2': {'availabilityStatus': 'Offline',
                                                                                'operationalState': 'Disabled'},
         '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/NRBTS_R-50304/NRCELL_R-1': {'administrativeState': 'Unlocked'}}
        :type statuses: {str: {str: str}}
        :param stop_conditions: data of statuses which should stop status watch;
                                should be in form of dictionary {component: {name: value}});
                                use None for value when expecting status without value (i.e. 'Online' after CNI-61110)
        i.e.
        {'/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-2': {'availabilityStatus': 'Online',
                                                                                'operationalState': 'Enabled'}}
        :type stop_conditions: {str: {str: str}}
        :param check_component: flag indicating whether component existence should be checked before adding
                        expected statuses; defaults to False
        :type check_component: bool
        :raises WatchdogNotStarted: when performing this action was not preceded with starting status watch
        :raises InvalidStatus: when expected status or stop condition has invalid data
        :raises ComponentCheckError: when BTS was unavailable during component check or
                                     given component doesn't exist on BTS
        """
        self._logger.info("Adding expected statuses:\n{}\n with stop conditions:\n{}".format(
            statuses, stop_conditions
        ))
        self._check_for_not_initialized_watchdog(self.expect_statuses_with_stop_conditions.__name__)

        watched_statuses = []
        for component, names_and_values in statuses.items():
            if not names_and_values:
                names_and_values = {None: None}

            watched_statuses += self._watchdog.add_expected_statuses(
                component=component, names_and_values=names_and_values, check_component=check_component
            )

        for component, names_and_values in stop_conditions.items():
            if not names_and_values:
                names_and_values = {None: None}

            self._watchdog.add_stop_conditions(component=component, names_and_values=names_and_values,
                                               watched_statuses=watched_statuses)

    def check_unexpected_statuses(self):
        """
        Checks whether watch history contains any unexpected statuses.

        Before using this keyword status watchdog needs to be started - watch_statuses keyword must be used first.
        Status watching will be continued despite any unexpected statuses being detected or not.

        :raises WatchdogNotStarted: when performing this action was not preceded with starting status watch
        :raises UnexpectedStatusesDetected: when watch history contains any unexpected status
        """
        self._logger.info("Checking unexpected statuses")
        self._check_for_not_initialized_watchdog(self.check_unexpected_statuses.__name__)
        self._watchdog.check_unexpected_statuses()

    def stop_watching_statuses(self):
        """
        Stops watching current statuses on BTS.

        Required to use every time when watch_statuses keyword is used.
        Stops status watching sub-thread which was run in background, disconnects from BTS and resets watchdog state,
        so it is recommended to use it in test's teardown.
        It is allowed to use this keyword even if statuses watching was already stopped before (or not started at all).
        """
        self._logger.info("Stopping status watch")

        if self._watchdog:
            self._watchdog.stop_watching_statuses()

        self._logger.info("Watching statuses has been stopped")

    def _check_for_not_initialized_watchdog(self, action):
        if not self._watchdog:
            raise WatchdogNotStarted("Before using {} watchdog must be started first - "
                                     "use watch_statuses".format(action))
